// src/models/services/EmailService.js
import { projectFirestore as db } from './firebase/config';

export const EmailService = {
  async sendCertificateEmail(userEmail, certificateData, pdfUrl) {
    try {
      const emailData = {
        to: userEmail,
        template: {
          name: 'certificate-issued',
          data: {
            studentName: certificateData.studentName,
            courseTitle: certificateData.courseTitle,
            finalScore: certificateData.finalScore,
            issueDate: new Date(certificateData.issueDate).toLocaleDateString('fr-FR'),
            certificateUrl: pdfUrl,
            verificationUrl: `${window.location.origin}/verify-certificate/${certificateData.certificateId}`,
            platformName: certificateData.platformName || 'EduPlatform'
          }
        },
        subject: `🎓 Votre certificat pour "${certificateData.courseTitle}"`,
        createdAt: new Date()
      };

      // Stocker dans Firestore pour déclencher une Cloud Function
      await db.collection('emailQueue').add(emailData);
      
      console.log('📧 Email programmé pour:', userEmail);
      return true;
    } catch (error) {
      console.error('❌ Erreur envoi email:', error);
      // Ne pas bloquer la génération du certificat si l'email échoue
      return false;
    }
  },

  async sendWelcomeCertificate(userId, certificateData, pdfUrl) {
    try {
      // Récupérer l'email de l'utilisateur
      const userDoc = await db.collection('users').doc(userId).get();
      if (!userDoc.exists) {
        console.warn('Utilisateur non trouvé pour envoi email');
        return false;
      }
      
      const userData = userDoc.data();
      const userEmail = userData.email;
      
      if (!userEmail) {
        console.warn('Email utilisateur non disponible');
        return false;
      }

      return await this.sendCertificateEmail(userEmail, certificateData, pdfUrl);
    } catch (error) {
      console.error(' Erreur envoi email bienvenue:', error);
      return false;
    }
  }
};
